(() => {
  // sdk/plugins/examples/hello/main.js
  (async () => {
    document.getElementById("title").textContent = (await caiyun.settings()).greeting;
    const input = document.getElementById("draft");
    input.value = await caiyun.storage.get("draft") || "";
    document.getElementById("save").onclick = async () => {
      try {
        await caiyun.storage.set("draft", input.value);
        document.getElementById("state").textContent = "\u5DF2\u4FDD\u5B58";
      } catch {
        document.getElementById("state").textContent = "\u4FDD\u5B58\u5931\u8D25\uFF0C\u5185\u5BB9\u4ECD\u7559\u5728\u8F93\u5165\u6846";
      }
    };
  })();
})();
